/**
 * Rigged 25-bone 3D human hand GLB models (left.glb & right.glb)
 * from the official W3C/Immersive Web @webxr-input-profiles/assets (MIT License).
 */
export const LEFT_HAND_GLB_BASE64 = "";
export const RIGHT_HAND_GLB_BASE64 = "";

export function decodeBase64ToArrayBuffer(b64: string): ArrayBuffer {
  const binary = atob(b64);
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes.buffer;
}
